import { DEVELOPER, NUMBER, USER, AGE, SINGLE } from "./actionTypes";

export const initialState = {
  developers: [],
  user: { id: 1, name: "Mary" },
  arr: [],
};

const newArr = [];

function reducer(state = initialState, action) {
  switch (action.type) {
    case NUMBER:
      return { ...state, arr: [...state.arr, action.payload] };
    case AGE:
      return { ...state, user: { ...state.user, age: action.payload } };
    case DEVELOPER:
      return { ...state, developers: [...state.developers, action.payload] };
    case USER:
      return {
        ...state,
        user: { id: state.user.id + 1, name: action.payload },
      };
    case SINGLE:
      initialState.arr.filter((elm, i) => (newArr[i] = elm > 9));
      console.log(newArr);

      return { ...state, arr: newArr };
    default:
      return state;
  }
}

export default reducer;
